import json
import gurobipy as gp

# Problem data
a = [3, 1, 2]
c = [5, 10, 8]
u = [4, 6, 3]
b = 4

# Formulation
model_data = {
    "variables": [
        {"name": "X0", "type": "int", "lb": 0, "ub": 4},
        {"name": "X1", "type": "int", "lb": 0, "ub": 6},
        {"name": "X2", "type": "int", "lb": 0, "ub": 3}
    ],
    "constraints": [
        {"name": "c1", "lhs": [{"coef": 1/3, "var": "X0"}, {"coef": 1, "var": "X1"}, {"coef": 1/2, "var": "X2"}], "op": "<=", "rhs": 4}
    ],
    "objective": {"sense": "max", "lhs": [{"coef": 5, "var": "X0"}, {"coef": 10, "var": "X1"}, {"coef": 8, "var": "X2"}]}
}

# Create a new model
m = gp.Model()

# Add variables
X = [m.addVar(vtype=gp.GRB.INTEGER, lb=model_data["variables"][i]["lb"], ub=model_data["variables"][i]["ub"], name=model_data["variables"][i]["name"]) for i in range(len(model_data["variables"]))]

# Set objective
m.setObjective(sum(model_data["objective"]["lhs"][i]["coef"] * X[i] for i in range(len(X))), gp.GRB.MAXIMIZE)

# Add constraints
m.addConstr(sum(model_data["constraints"][0]["lhs"][i]["coef"] * X[i] for i in range(len(X))) <= model_data["constraints"][0]["rhs"], name=model_data["constraints"][0]["name"])

# Optimize the model
m.optimize()

# Print the solution
print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))
